package com.betterpotionstorage;

import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.ScriptID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.util.Text;
import net.runelite.api.ChatMessageType;

/**
 * Borrows / mirrors the Bank Tags plugin.
 *
 * - POTIONSTORE_DOSES / POTIONSTORE_WITHDRAW_DOSES scripts (mirrors PotionStorage.rebuildPotions())
 * - Widget structure: 5 children per potion, clickable offset 1 (mirrors PotionStorage.prepareWidgets())
 * - Potion matching: finding storage slots by checking all dose variants (mirrors PotionStorage.matches() / findPotion())
 * - Dose change 1007
 *
 * - net.runelite.client.plugins.banktags.tabs.PotionStorage
 * - net.runelite.client.plugins.banktags.BankTagsPlugin
 */
@Slf4j
@Singleton
public class BetterPotionStorageManager {

    private final Client client;
    private final ClientThread clientThread;
    private final ItemManager itemManager;
    private final TagManager tagManager;
    private final BankTagsPlugin bankTagsPlugin;
    private final LayoutManager layoutManager;

    public static final String TAG_NAME = "potstash";
    public static final int POTIONSTORE_WIDGET = 786490;
    public static final int WIDGETS_PER_POTION = 5;
    public static final int CLICKABLE_OFFSET = 1;

    // ID for potions currently in storage.
    @Getter
    private final Set<Integer> cachedStoragePotions = new HashSet<>();

    // ID for All potions that can be stored in potion storage.
    @Getter
    private final Set<Integer> validMenuPotions = new HashSet<>();

    @Inject
    public BetterPotionStorageManager(
            Client client,
            ClientThread clientThread,
            ItemManager itemManager,
            TagManager tagManager,
            BankTagsPlugin bankTagsPlugin,
            LayoutManager layoutManager
    ) {
        this.client = client;
        this.clientThread = clientThread;
        this.itemManager = itemManager;
        this.tagManager = tagManager;
        this.bankTagsPlugin = bankTagsPlugin;
        this.layoutManager = layoutManager;
    }

    /**
     * Reads Potion Storage / dose state.
     * Call on client thread.
     */
    public void syncStorageCache() {
        cachedStoragePotions.clear();
        validMenuPotions.clear();

        EnumComposition potionStorePotions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
        EnumComposition potionStoreUnfinishedPotions = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

        if (potionStorePotions == null || potionStoreUnfinishedPotions == null) return;

        for (EnumComposition e : new EnumComposition[]{potionStorePotions, potionStoreUnfinishedPotions}) {
            for (int potionEnumId : e.getIntVals()) {
                EnumComposition potionEnum = client.getEnum(potionEnumId);
                if (potionEnum == null) continue;

                // Every dose variant
                for (int dose = 1; dose <= 4; dose++) {
                    int doseItemId = potionEnum.getIntValue(dose);
                    if (doseItemId > 0) {
                        validMenuPotions.add(itemManager.canonicalize(doseItemId));
                    }
                }

                // How many total doses
                client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
                int totalDoses = client.getIntStack()[0];

                if (totalDoses > 0) {
                    // Check X dose state
                    client.runScript(ScriptID.POTIONSTORE_WITHDRAW_DOSES, potionEnumId);
                    int withdrawDoses = client.getIntStack()[0];
                    int withdrawItemId = potionEnum.getIntValue(withdrawDoses);
                    if (withdrawItemId > 0) {
                        cachedStoragePotions.add(itemManager.canonicalize(withdrawItemId));
                    }
                }
            }
        }
    }

    /**
     * Makes sure the potion storage interface is loaded.
     * Call on client thread.
     */
    public void prepareWidgets() {
        Widget potStoreContent = client.getWidget(POTIONSTORE_WIDGET);
        if (potStoreContent == null) return;

        Widget[] children = potStoreContent.getChildren();
        if (children != null && children.length > 0) return;

        EnumComposition potionStorePotions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
        EnumComposition potionStoreUnfinishedPotions = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

        if (potionStorePotions == null || potionStoreUnfinishedPotions == null) return;

        int totalPotions = potionStorePotions.getIntVals().length + potionStoreUnfinishedPotions.getIntVals().length;
        int childIdx = 0;
        for (int i = 0; i < totalPotions; i++) {
            for (int j = 0; j < WIDGETS_PER_POTION; j++) {
                potStoreContent.createChild(childIdx++, WidgetType.GRAPHIC);
            }
        }
    }

    /**
     * Unfinished potions only have 1 dose and cannot be changed.
     * @return true if potion supports dose changes
     */
    public boolean supportsDoseChange(int itemId) {
        int potionEnumId = getEnumIdForItem(itemId);
        if (potionEnumId == -1) return false;

        EnumComposition potionEnum = client.getEnum(potionEnumId);
        if (potionEnum == null) return false;

        int validDoses = 0;
        for (int dose = 1; dose <= 4; dose++) {
            int doseItemId = potionEnum.getIntValue(dose);
            if (doseItemId > 0) {
                validDoses++;
            }
        }
        return validDoses > 1;
    }

    /**
     * Bank-tags fix: Dupe potions with different doses won't remove from layout.
     * Removes a potion from the layout by its position (widget index).
     * @param position The widget index (layout position) to remove.
     */
    public void removeAtPosition(int position) {
        String activeTag = bankTagsPlugin.getActiveTag();
        if (activeTag == null) return;

        Layout currentLayout = layoutManager.loadLayout(activeTag);
        if (currentLayout == null) return;

        int[] layoutArray = currentLayout.getLayout();
        if (position < 0 || position >= layoutArray.length) return;

        int itemId = layoutArray[position];
        if (itemId == -1) return;

        // Remove from layout by position
        layoutArray[position] = -1;
        layoutManager.saveLayout(new Layout(activeTag, layoutArray));

        // Remove the tag for this item
        tagManager.removeTag(itemId, activeTag);

        // Reload the tab
        bankTagsPlugin.openBankTag(activeTag);
    }

    /**
     * Where a specific potion sits in the potion storage.
     * @param canonicalItemId Item ID of any dose.
     * @return The widget index, or -1 if not found.
     */
    public int getWidgetIndex(int canonicalItemId) {
        EnumComposition potionStorePotions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
        EnumComposition potionStoreUnfinishedPotions = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

        if (potionStorePotions == null || potionStoreUnfinishedPotions == null) return -1;

        int position = -1;

        int[] regularVals = potionStorePotions.getIntVals();
        for (int i = 0; i < regularVals.length; i++) {
            EnumComposition potionEnum = client.getEnum(regularVals[i]);
            if (potionEnum == null) continue;

            for (int dose = 1; dose <= 4; dose++) {
                int doseItemId = potionEnum.getIntValue(dose);
                if (doseItemId > 0 && itemManager.canonicalize(doseItemId) == canonicalItemId) {
                    position = i;
                    break;
                }
            }
            if (position != -1) break;
        }

        if (position == -1) {
            int[] unfinishedVals = potionStoreUnfinishedPotions.getIntVals();
            for (int i = 0; i < unfinishedVals.length; i++) {
                EnumComposition potionEnum = client.getEnum(unfinishedVals[i]);
                if (potionEnum == null) continue;

                for (int dose = 1; dose <= 4; dose++) {
                    int doseItemId = potionEnum.getIntValue(dose);
                    if (doseItemId > 0 && itemManager.canonicalize(doseItemId) == canonicalItemId) {
                        position = regularVals.length + i;
                        break;
                    }
                }
                if (position != -1) break;
            }
        }

        if (position == -1) return -1;

        return position * WIDGETS_PER_POTION + CLICKABLE_OFFSET;
    }

    /**
     * Finds potion slot from the potion item ID.
     * Returns -1 if the item isn't a potion that can be stored.
     * @param itemId ID of any dose of a potion
     * @return The storage slot ID or -1 if it's not a storable potion
     */
    public int getEnumIdForItem(int itemId) {
        int canonicalItemId = itemManager.canonicalize(itemId);

        EnumComposition potionStorePotions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
        EnumComposition potionStoreUnfinishedPotions = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);

        if (potionStorePotions == null || potionStoreUnfinishedPotions == null) return -1;

        for (EnumComposition e : new EnumComposition[]{potionStorePotions, potionStoreUnfinishedPotions}) {
            for (int potionEnumId : e.getIntVals()) {
                EnumComposition potionEnum = client.getEnum(potionEnumId);
                if (potionEnum == null) continue;

                for (int dose = 1; dose <= 4; dose++) {
                    int doseItemId = potionEnum.getIntValue(dose);
                    if (doseItemId > 0 && itemManager.canonicalize(doseItemId) == canonicalItemId) {
                        return potionEnumId;
                    }
                }
            }
        }
        return -1;
    }


    /**
     * Ensures the bank tag layout exists. Called once on startup.
     */
    public void rebuildPotionTag() {
        Layout currentLayout = layoutManager.loadLayout(TAG_NAME);
        if (currentLayout == null) {
            layoutManager.saveLayout(new Layout(TAG_NAME, new int[0]));
        }
    }

    /**
     * Syncs the bank tag with potion storage.
     * @param forceOpenTab Whether to force the tab open after syncing.
     */
    public void loadPotionsFromStorage(boolean forceOpenTab) {
        syncStorageCache();

        Layout currentLayout = layoutManager.loadLayout(TAG_NAME);
        List<Integer> layoutList = new ArrayList<>();

        if (currentLayout != null) {
            for (int id : currentLayout.getLayout()) layoutList.add(id);
        }

        // Remove empty slots at the end of the layout
        while (!layoutList.isEmpty() && layoutList.get(layoutList.size() - 1) == -1) {
            layoutList.remove(layoutList.size() - 1);
        }

        boolean modified = false;

        // Build a map of what's already in the layout by potion type
        Map<Integer, Integer> layoutEnumMap = new HashMap<>();
        for (int id : layoutList) {
            int enumId = getEnumIdForItem(id);
            if (enumId != -1) {
                layoutEnumMap.put(enumId, id);
            }
        }

        // Compare layout to potions in potion storage
        for (int canonicalId : cachedStoragePotions) {
            tagManager.addTag(canonicalId, TAG_NAME, false);

            int enumId = getEnumIdForItem(canonicalId);
            if (enumId == -1) continue;

            if (layoutEnumMap.containsKey(enumId)) {
                // Potion is already in the layout
                int existingItemId = layoutEnumMap.get(enumId);
                if (existingItemId != canonicalId) {
                    // Dose changed, update the layout
                    int index = layoutList.indexOf(existingItemId);
                    if (index != -1) {
                        layoutList.set(index, canonicalId);
                        modified = true;
                    }
                    tagManager.removeTag(existingItemId, TAG_NAME);
                    layoutEnumMap.put(enumId, canonicalId);
                }
            } else {
                // New potion, add to the layout
                layoutList.add(canonicalId);
                layoutEnumMap.put(enumId, canonicalId);
                modified = true;
            }
        }

        if (modified) {
            int[] newArray = layoutList.stream().mapToInt(Integer::intValue).toArray();
            layoutManager.saveLayout(new Layout(TAG_NAME, newArray));
        }

        if (forceOpenTab) {
            clientThread.invokeLater(() -> bankTagsPlugin.openBankTag(TAG_NAME));
        }
    }

    public void loadPotionsFromStorage() {
        loadPotionsFromStorage(true);
    }

    /**
     * Adds ALL potions (even those with 0 doses) from potion storage to the layout.
     */
    public void addEmptyPotions() {
        EnumComposition potionStorePotions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
        EnumComposition potionStoreUnfinishedPotions = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);
        if (potionStorePotions == null || potionStoreUnfinishedPotions == null) return;

        Layout currentLayout = layoutManager.loadLayout(TAG_NAME);
        List<Integer> layoutList = new ArrayList<>();
        if (currentLayout != null) {
            for (int id : currentLayout.getLayout()) layoutList.add(id);
        }
        while (!layoutList.isEmpty() && layoutList.get(layoutList.size() - 1) == -1) {
            layoutList.remove(layoutList.size() - 1);
        }

        boolean addedAny = false;
        for (EnumComposition e : new EnumComposition[]{potionStorePotions, potionStoreUnfinishedPotions}) {
            for (int potionEnumId : e.getIntVals()) {
                EnumComposition potionEnum = client.getEnum(potionEnumId);
                if (potionEnum == null) continue;

                // Check 0 doses
                client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
                int totalDoses = client.getIntStack()[0];

                if (totalDoses == 0) {
                    // Find icon
                    for (int dose = 4; dose >= 1; dose--) {
                        int itemId = potionEnum.getIntValue(dose);
                        if (itemId > 0) {
                            int canonicalId = itemManager.canonicalize(itemId);
                            if (!layoutList.contains(canonicalId)) {
                                tagManager.addTag(canonicalId, TAG_NAME, false);
                                layoutList.add(canonicalId);
                                addedAny = true;
                            }
                            break;
                        }
                    }
                }
            }
        }

        if (addedAny) {
            int[] newArray = layoutList.stream().mapToInt(Integer::intValue).toArray();
            layoutManager.saveLayout(new Layout(TAG_NAME, newArray));
            if (TAG_NAME.equals(bankTagsPlugin.getActiveTag())) {
                clientThread.invokeLater(() -> bankTagsPlugin.openBankTag(TAG_NAME));
            }
        }
    }

    /**
     * Removes potions with 0 doses from the layout and tags.
     */
    public void removeEmptyPotions() {
        EnumComposition potionStorePotions = client.getEnum(EnumID.POTIONSTORE_POTIONS);
        EnumComposition potionStoreUnfinishedPotions = client.getEnum(EnumID.POTIONSTORE_UNFINISHED_POTIONS);
        if (potionStorePotions == null || potionStoreUnfinishedPotions == null) return;

        // Map of all potion items, track which slots have 0 doses
        Map<Integer, Integer> itemToEnumMap = new HashMap<>();
        Set<Integer> emptyPotionEnums = new HashSet<>();

        for (EnumComposition e : new EnumComposition[]{potionStorePotions, potionStoreUnfinishedPotions}) {
            for (int potionEnumId : e.getIntVals()) {
                EnumComposition potionEnum = client.getEnum(potionEnumId);
                if (potionEnum == null) continue;

                client.runScript(ScriptID.POTIONSTORE_DOSES, potionEnumId);
                int totalDoses = client.getIntStack()[0];

                if (totalDoses == 0) {
                    emptyPotionEnums.add(potionEnumId);
                }

                for (int dose = 1; dose <= 4; dose++) {
                    int itemId = potionEnum.getIntValue(dose);
                    if (itemId > 0) {
                        itemToEnumMap.put(itemManager.canonicalize(itemId), potionEnumId);
                    }
                }
            }
        }

        Layout currentLayout = layoutManager.loadLayout(TAG_NAME);
        List<Integer> layoutList = new ArrayList<>();
        if (currentLayout != null) {
            for (int id : currentLayout.getLayout()) layoutList.add(id);
        }

        boolean layoutModified = false;
        Collection<Integer> taggedItems = tagManager.getItemsForTag(TAG_NAME);

        // Remove layout entries that belong to empty potion slots
        for (int itemId : taggedItems) {
            int canonicalId = itemManager.canonicalize(itemId);
            Integer potionEnumId = itemToEnumMap.get(canonicalId);

            if (potionEnumId != null && emptyPotionEnums.contains(potionEnumId)) {
                tagManager.removeTag(itemId, TAG_NAME);
                if (layoutList.contains(canonicalId)) {
                    layoutList.remove(Integer.valueOf(canonicalId));
                    layoutModified = true;
                }
            }
        }

        if (layoutModified) {
            while (!layoutList.isEmpty() && layoutList.get(layoutList.size() - 1) == -1) {
                layoutList.remove(layoutList.size() - 1);
            }
            int[] newArray = layoutList.stream().mapToInt(Integer::intValue).toArray();
            layoutManager.saveLayout(new Layout(TAG_NAME, newArray));
        }

        if (TAG_NAME.equals(bankTagsPlugin.getActiveTag())) {
            clientThread.invokeLater(() -> bankTagsPlugin.openBankTag(TAG_NAME));
        }
    }


    // Export potstash tag n layout to the clipboard using Bank Tags format
    public void exportStash() {
        Layout layout = layoutManager.loadLayout(TAG_NAME);
        Collection<Integer> taggedItems = tagManager.getItemsForTag(TAG_NAME);

        List<String> data = new ArrayList<>();
        data.add("banktags");
        data.add("1");
        data.add(TAG_NAME);

        int icon = -1;
        if (layout != null) {
            for (int id : layout.getLayout()) {
                if (id != -1) {
                    icon = id;
                    break;
                }
            }
        }
        if (icon == -1 && !taggedItems.isEmpty()) {
            icon = taggedItems.iterator().next();
        }
        data.add(String.valueOf(icon));

        for (Integer item : taggedItems) {
            if (layout == null || layout.count(item) == 0) {
                data.add(String.valueOf(item));
            }
        }

        if (layout != null) {
            data.add("layout");
            int[] l = layout.getLayout();
            for (int idx = 0; idx < l.length; idx++) {
                if (l[idx] != -1) {
                    data.add(String.valueOf(idx));
                    data.add(String.valueOf(l[idx]));
                }
            }
        }

        StringSelection selection = new StringSelection(Text.toCSV(data));
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);

        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
                "Pot Stash: Exported to clipboard (" + taggedItems.size() + " items).", null);
    }
}

package com.betterpotionstorage;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("betterpotionstorage")
public interface BetterPotionStorageConfig extends Config {

    @ConfigSection(
            name = "General",
            description = "Pot Stash Settings",
            position = 0
    )
    String generalSection = "generalSection";

    @ConfigItem(
            keyName = "autoUpdateStash",
            name = "Automatically update stash",
            description = "Automatically sync the Stash when opened",
            position = 1,
            section = generalSection
    )
    default boolean autoUpdateStash() {
        return false;
    }

    @ConfigItem(
            keyName = "addToStashMenu",
            name = "Show 'Add to Stash'",
            description = "Show 'Add to Stash' option when right-clicking bank items",
            position = 2,
            section = generalSection
    )
    default boolean addToStashMenu() {
        return true;
    }

    @ConfigItem(
            keyName = "doseOptionsAllTags",
            name = "Show 'Set Dose' in all tabs",
            description = "Show 'Set dose' options in all bank-tag tabs, not just Pot Stash",
            position = 3,
            section = generalSection
    )
    default boolean doseOptionsAllTags() {
        return false;
    }

    @ConfigSection(
            name = "Empty Potions",
            description = "Manage empty potion placeholders",
            position = 10
    )
    String emptySection = "emptySection";

    @ConfigItem(
            keyName = "addEmptyPotions",
            name = "Add empty potions to stash",
            description = "Adds placeholder potions that have zero doses in storage",
            position = 11,
            section = emptySection
    )
    default boolean addEmptyPotions() {
        return false;
    }

    @ConfigItem(
            keyName = "removeEmptyPotions",
            name = "Remove empty potions from stash",
            description = "Remove placeholder potions that have zero doses in storage",
            position = 12,
            section = emptySection
    )
    default boolean removeEmptyPotions() {
        return false;
    }
}

package com.betterpotionstorage;

import javax.inject.Inject;

import com.google.inject.Provides;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.TagManager;


@Slf4j
@PluginDescriptor(
		name = "Pot Stash",
		description = "Use Bank Tags instead of Potion Storage",
		tags = {"bank", "tag", "potion", "storage", "stash",}
)
@PluginDependency(BankTagsPlugin.class)
public class BetterPotionStoragePlugin extends Plugin {

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private TagManager tagManager;

	@Inject
	private BankTagsPlugin bankTagsPlugin;

	@Inject
	private ItemManager itemManager;

	@Inject
	private BetterPotionStorageConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BetterPotionStorageManager potionStorageManager;

	private boolean wasTabActive = false;
	private boolean hasDoneFirstOpen = false;

	@Provides
	BetterPotionStorageConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(BetterPotionStorageConfig.class);
	}

	@Override
	protected void startUp() throws Exception {
		clientThread.invokeLater(() -> {
			potionStorageManager.rebuildPotionTag();
			potionStorageManager.syncStorageCache();

			String firstOpenDone = configManager.getConfiguration("betterpotionstorage", "firstTabOpenDone");
			hasDoneFirstOpen = "true".equals(firstOpenDone);
		});
	}

	@Override
	protected void shutDown() throws Exception {
		clientThread.invokeLater(() -> {
			if (BetterPotionStorageManager.TAG_NAME.equals(bankTagsPlugin.getActiveTag())) {
				bankTagsPlugin.closeBankTag();
			}
		});
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (event.getGroup().equals("betterpotionstorage")) {
			if (event.getKey().equals("addEmptyPotions") && config.addEmptyPotions()) {
				if (client.getGameState() == GameState.LOGGED_IN) {
					clientThread.invokeLater(potionStorageManager::addEmptyPotions);
				}
				configManager.setConfiguration("betterpotionstorage", "addEmptyPotions", false);
			} else if (event.getKey().equals("removeEmptyPotions") && config.removeEmptyPotions()) {
				if (client.getGameState() == GameState.LOGGED_IN) {
					clientThread.invokeLater(potionStorageManager::removeEmptyPotions);
				}
				configManager.setConfiguration("betterpotionstorage", "removeEmptyPotions", false);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		boolean isTabActive = BetterPotionStorageManager.TAG_NAME.equals(bankTagsPlugin.getActiveTag());

		if (isTabActive && !wasTabActive) {
			if (!hasDoneFirstOpen) {
				clientThread.invokeLater(() -> potionStorageManager.loadPotionsFromStorage());
				hasDoneFirstOpen = true;
				configManager.setConfiguration("betterpotionstorage", "firstTabOpenDone", "true");
			} else if (config.autoUpdateStash()) {
				clientThread.invokeLater(() -> potionStorageManager.loadPotionsFromStorage());
			}
		}

		wasTabActive = isTabActive;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event) {
		if (event.getOption() != null && event.getOption().toLowerCase().contains("potion storage")) {
			if (event.getType() != MenuAction.CC_OP.getId()
					&& event.getType() != MenuAction.CC_OP_LOW_PRIORITY.getId()) {
				return;
			}

			if (!config.autoUpdateStash()) {
				client.getMenu().createMenuEntry(-1)
						.setOption("Update Stash")
						.setTarget(event.getTarget())
						.setType(MenuAction.RUNELITE)
						.setIdentifier(event.getIdentifier())
						.setParam0(event.getActionParam0())
						.setParam1(event.getActionParam1());
			}

			client.getMenu().createMenuEntry(-1)
					.setOption("Export Stash")
					.setTarget(event.getTarget())
					.setType(MenuAction.RUNELITE)
					.setIdentifier(event.getIdentifier())
					.setParam0(event.getActionParam0())
					.setParam1(event.getActionParam1());

			client.getMenu().createMenuEntry(-1)
					.setOption("Open Stash")
					.setTarget(event.getTarget())
					.setType(MenuAction.RUNELITE)
					.setIdentifier(event.getIdentifier())
					.setParam0(event.getActionParam0())
					.setParam1(event.getActionParam1());
		}
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event) {
		Menu menu = client.getMenu();

		MenuEntry bankItemEntry = null;
		for (MenuEntry entry : event.getMenuEntries()) {
			if (entry.getParam1() == net.runelite.api.gameval.InterfaceID.Bankmain.ITEMS && entry.getItemId() > 0) {
				bankItemEntry = entry;
				break;
			}
		}

		if (bankItemEntry != null) {
			boolean isPotStashTab = BetterPotionStorageManager.TAG_NAME.equals(bankTagsPlugin.getActiveTag());

			if (config.addToStashMenu() && !isPotStashTab) {
				boolean hasAddToStash = false;
				for (MenuEntry e : event.getMenuEntries()) {
					if ("Add to Stash".equals(e.getOption())) {
						hasAddToStash = true;
						break;
					}
				}

				if (!hasAddToStash) {
					menu.createMenuEntry(2)
							.setOption("Add to Stash")
							.setTarget(bankItemEntry.getTarget())
							.setType(MenuAction.RUNELITE)
							.setIdentifier(bankItemEntry.getIdentifier())
							.setParam0(bankItemEntry.getParam0())
							.setParam1(bankItemEntry.getParam1())
							.setItemId(bankItemEntry.getItemId());
				}
			}

			boolean showDoseOptions = config.doseOptionsAllTags()
					? bankTagsPlugin.getActiveTag() != null
					: isPotStashTab;

			if (showDoseOptions) {
				int itemId = bankItemEntry.getItemId();
				if (itemId > 0 && potionStorageManager.getEnumIdForItem(itemId) != -1) {
					boolean hasRemoveLayout = false;
					for (MenuEntry e : event.getMenuEntries()) {
						if ("Remove-layout".equals(e.getOption())) {
							hasRemoveLayout = true;
							break;
						}
					}

					if (!hasRemoveLayout) {
						menu.createMenuEntry(-8)
								.setOption("Remove-layout")
								.setTarget(bankItemEntry.getTarget())
								.setType(MenuAction.RUNELITE)
								.setIdentifier(bankItemEntry.getIdentifier())
								.setParam0(bankItemEntry.getParam0())
								.setParam1(bankItemEntry.getParam1())
								.setItemId(bankItemEntry.getItemId());
					}
				}
			}

			if (showDoseOptions) {
				int canonicalId = itemManager.canonicalize(bankItemEntry.getItemId());
				if (potionStorageManager.getValidMenuPotions().contains(canonicalId)
						&& potionStorageManager.supportsDoseChange(bankItemEntry.getItemId())) {

					potionStorageManager.prepareWidgets();

					int widgetIndex = potionStorageManager.getWidgetIndex(canonicalId);

					if (widgetIndex != -1) {
						for (int dose = 4; dose >= 1; dose--) {
							int doseMenuId = dose + 5;

							menu.createMenuEntry(-9)
									.setOption("Set " + dose + " dose")
									.setTarget(bankItemEntry.getTarget())
									.setType(MenuAction.CC_OP)
									.setParam0(widgetIndex)
									.setParam1(BetterPotionStorageManager.POTIONSTORE_WIDGET)
									.setIdentifier(doseMenuId)
									.setItemId(bankItemEntry.getItemId());
						}
					}
				}
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event) {
		if (event.getMenuOption() == null) return;

		String option = event.getMenuOption();

		if (event.getMenuAction() == MenuAction.RUNELITE
				&& event.getMenuOption().equals("Remove-layout")) {
			int itemId = event.getItemId();
			if (itemId > 0 && potionStorageManager.getEnumIdForItem(itemId) != -1) {
				event.consume();
				potionStorageManager.removeAtPosition(event.getParam0());
				return;
			}
		}

		boolean isVanillaButton = option.toLowerCase().contains("potion storage");
		boolean isCustomButton = "Pot Stash".equals(option);
		boolean isUpdateButton = "Update Stash".equals(option);
		boolean isExportButton = "Export Stash".equals(option);
		boolean isAddToTabButton = "Add to Stash".equals(option);

		if (isVanillaButton && !client.isMenuOpen()) {
			event.consume();
			clientThread.invokeLater(() -> bankTagsPlugin.openBankTag(BetterPotionStorageManager.TAG_NAME));
			return;
		}

		if (isCustomButton) {
			event.consume();
			clientThread.invokeLater(() -> bankTagsPlugin.openBankTag(BetterPotionStorageManager.TAG_NAME));
			return;
		}

		if (isUpdateButton) {
			event.consume();
			clientThread.invokeLater(() -> potionStorageManager.loadPotionsFromStorage());
			return;
		}

		if (isExportButton) {
			event.consume();
			clientThread.invokeLater(potionStorageManager::exportStash);
			return;
		}

		if (isAddToTabButton) {
			event.consume();
			int itemId = event.getItemId();
			if (itemId > 0) {
				int canonicalId = itemManager.canonicalize(itemId);
				tagManager.addTag(canonicalId, BetterPotionStorageManager.TAG_NAME, false);

				if (BetterPotionStorageManager.TAG_NAME.equals(bankTagsPlugin.getActiveTag())) {
					clientThread.invokeLater(() -> bankTagsPlugin.openBankTag(BetterPotionStorageManager.TAG_NAME));
				}
			}
		}
	}
